/** The public Gallery Worker's config (generated by `host-configs.ts`). */
import type { InfrastructureDefinition } from '../tenants/tenant-config.js';
import { WRANGLER_BASE } from '../tenants/wrangler-base.js';

/**
 * The public Gallery Worker: the public bucket and the canonical origin. `main` is the bundle that
 * `hearthlog gallery-public:build` writes beside the config: Svelte renders the page on the server.
 */
export function buildGalleryPublicConfig(infrastructure: InfrastructureDefinition) {
    return {
        name: infrastructure.galleryPublicWorker,
        main: './dist/worker/index.js',
        compatibility_date: WRANGLER_BASE.compatibility_date,
        // Svelte's server renderer keeps per-render context in AsyncLocalStorage.
        compatibility_flags: ['nodejs_als'],
        workers_dev: true,
        preview_urls: false,
        observability: { enabled: true },
        vars: { PUBLIC_ORIGIN: infrastructure.galleryPublicOrigin },
        r2_buckets: [{ binding: 'GALLERY_PUBLIC', bucket_name: infrastructure.galleryPublicBucket }],
    };
}
